-- Toujours utiliser l'UUID, jamais WHERE email= (profils peuvent ne pas avoir email)
UPDATE public.profiles SET role = 'admin' WHERE id = '<uuid-du-user>';
-- Récupérer l'UUID :
SELECT u.id, u.email, p.role FROM auth.users u LEFT JOIN public.profiles p ON p.id = u.id ORDER BY u.created_at DESC;
